import re

WEIGHTS = {'H': 1.008, 'O': 15.999, 'N': 14.007, 'Ca': 40.078, 'Mg': 24.305}

_TOKEN_RE = re.compile(r'([A-Z][a-z]?)(\d*)|(\()|(\))|(\d+)|(\S)')


def _tokenize(formula):
    tokens = []
    for sym, sym_count, lparen, rparen, digits, junk in _TOKEN_RE.findall(formula):
        if sym:
            tokens.append(('SYM', sym, int(sym_count or 1)))
        elif lparen:
            tokens.append(('LPAREN', None, None))
        elif rparen:
            tokens.append(('RPAREN', None, None))
        elif digits:
            raise ValueError(f'bare number {digits!r} in formula {formula!r}')
        elif junk:
            raise ValueError(f'unexpected character {junk!r} in formula {formula!r}')
    return tokens


def molar_mass(formula):
    """Compute molar mass of a chemical formula with nested groups, e.g. Ca(OH)2.

    Raises ValueError on unbalanced parentheses or malformed input.
    """
    tokens = _tokenize(formula)
    pos = 0

    def parse_group():
        nonlocal pos
        total = 0.0
        while pos < len(tokens):
            kind, value, count = tokens[pos]
            if kind == 'SYM':
                total += WEIGHTS[value] * count
                pos += 1
            elif kind == 'LPAREN':
                pos += 1                      # consume '('
                inner = parse_group()         # recurse for arbitrary nesting
                pos += 1                      # consume ')'
                total += inner * _multiplier()
            else:                             # RPAREN ends this group
                break
        return total

    def _multiplier():
        nonlocal pos
        # A multiplier is an optional integer token following a group.
        if pos < len(tokens) and tokens[pos][0] == 'DIGIT':
            n = tokens[pos][2]
            pos += 1
            return n
        return 1

    def _expect_close():
        nonlocal pos
        if pos >= len(tokens) or tokens[pos][0] != 'RPAREN':
            raise ValueError(f'unbalanced parentheses in formula {formula!r}')

    # Wrap parse so that every LPAREN's matching RPAREN/multiplier is validated.
    def parse_top():
        nonlocal pos
        total = 0.0
        depth = 0
        while pos < len(tokens):
            kind, value, count = tokens[pos]
            if kind == 'SYM':
                total += WEIGHTS[value] * count
                pos += 1
            elif kind == 'LPAREN':
                depth += 1
                pos += 1
                total += parse_group_checked()
            else:
                raise ValueError(f'unbalanced parentheses in formula {formula!r}')
        if depth != 0:
            raise ValueError(f'unbalanced parentheses in formula {formula!r}')
        return total

    def parse_group_checked():
        nonlocal pos
        inner_total = 0.0
        while pos < len(tokens):
            kind, value, count = tokens[pos]
            if kind == 'SYM':
                inner_total += WEIGHTS[value] * count
                pos += 1
            elif kind == 'LPAREN':
                pos += 1
                inner_total += parse_group_checked()
            else:  # RPAREN closes this group
                pos += 1
                mult = 1
                if pos < len(tokens) and tokens[pos][0] == 'MULT':
                    mult = tokens[pos][2]
                    pos += 1
                return inner_total * mult
        raise ValueError(f'unbalanced parentheses in formula {formula!r}')

    # Tag integer tokens that follow ')' as group multipliers.
    tagged = []
    for i, tok in enumerate(tokens):
        if tok[0] == 'SYM' or tok[0] in ('LPAREN', 'RPAREN'):
            tagged.append(tok)
        else:  # bare digits are invalid; only reachable via junk-free path
            tagged.append(tok)
    tokens = [(t[0], t[1], t[2]) for t in tokens]

    return parse_top()

