import re

WEIGHTS = {'H': 1.008, 'O': 15.999, 'N': 14.007, 'Ca': 40.078, 'Mg': 24.305}

_TOKEN_RE = re.compile(r'([A-Z][a-z]?)(\d*)|(\()|(\))|(\d+)|(\S)')


def _tokenize(formula):
    """Yield tokens: ('SYM', symbol, count), ('LPAREN',), ('RPAREN',), ('NUM', n)."""
    for sym, sym_count, lparen, rparen, digits, junk in _TOKEN_RE.findall(formula):
        if sym:
            yield ('SYM', sym, int(sym_count or 1))
        elif lparen:
            yield ('LPAREN',)
        elif rparen:
            yield ('RPAREN',)
        elif digits:
            raise ValueError(f'bare number {digits!r} in formula {formula!r}')
        else:
            raise ValueError(f'unexpected character {junk!r} in formula {formula!r}')


def molar_mass(formula):
    """Molar mass of a chemical formula supporting nested groups, e.g. Ca(OH)2.

    Raises ValueError on unbalanced parentheses or malformed input.
    """
    tokens = list(_tokenize(formula))

    # A group multiplier must directly follow ')' — mark those NUMs as MULT.
    tagged = []
    for i, tok in enumerate(tokens):
        if tok[0] == 'RPAREN' and i + 1 < len(tokens) and tokens[i + 1][0] == 'NUM':
            tagged.append(('MULT', None, tokens[i + 1][1]))
            continue
        if tok[0] == 'NUM':
            continue  # already consumed as a multiplier
        tagged.append(tok)

    pos = 0

    def parse_group():
        """Parse until matching ')' (consumed); return unmultiplied mass."""
        nonlocal pos
        total = 0.0
        while pos < len(tagged):
            tok = tagged[pos]
            if tok[0] == 'SYM':
                total += WEIGHTS[tok[1]] * tok[2]
                pos += 1
            elif tok[0] == 'LPAREN':
                pos += 1
                total += parse_group()
            else:  # RPAREN closes this group
                break
        return total * _close_group()

    def _close_group():
        nonlocal pos
        if pos >= len(tagged) or tagged[pos][0] != 'RPAREN':
            raise ValueError(f'unbalanced parentheses in formula {formula!r}')
        pos += 1
        mult = 1
        if pos < len(tagged) and tagged[pos][0] == 'MULT':
            mult = tagged[pos][2]
            pos += 1
        return mult

    def parse_top():
        nonlocal pos
        total = 0.0
        while pos < len(tagged):
            tok = tagged[pos]
            if tok[0] == 'SYM':
                total += WEIGHTS[tok[1]] * tok[2]
                pos += 1
            elif tok[0] == 'LPAREN':
                pos += 1
                total += parse_group()
            else:  # stray RPAREN at top level
                raise ValueError(f'unbalanced parentheses in formula {formula!r}')
        return total

    return parse_top()

